import {VERSION,initial,actions,apply,describe} from './engine.js';
export const SAVE_FORMAT='chess-v2-match/1';
export function exportMatch(journal,settings={}){return {format:SAVE_FORMAT,rulesVersion:VERSION,savedAt:new Date().toISOString(),settings,moves:journal.map(e=>e.action)};}
export function restoreMatch(data){if(!data||data.format!==SAVE_FORMAT||data.rulesVersion!==VERSION||!Array.isArray(data.moves)||data.moves.length>5000)throw new Error('This is not a supported Chess V2 match file.');let state=initial();const past=[],journal=[];for(const raw of data.moves){if(!raw||typeof raw.id!=='string'||raw.id.length>2000)throw new Error('Invalid action in match file.');const action=actions(state).find(a=>a.id===raw.id);if(!action)throw new Error('Match contains an illegal action.');past.push(state);if(past.length>200)past.shift();journal.push({action,text:describe(state,action),color:state.turn,turn:state.ply+1});state=apply(state,action);}const settings={opponent:data.settings?.opponent==='local'?'local':'practice',flipped:!!data.settings?.flipped};return {state,past,journal,settings};}
